  function starterContent(fileName) {
    const extension = (fileName.split(".").pop() || "").toLowerCase();
    const base = (fileName.split("/").pop() || "page").replace(/\.[^.]+$/, "");
    const component = base.split(/[^A-Za-z0-9]+/).filter(Boolean).map((part) => part[0].toUpperCase() + part.slice(1)).join("") || "Page";
    const className = base.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "page";
    if (extension === "tsx" || extension === "jsx") {
      return `export default function ${component}() {
  return (
    <main className="${className}">
      <h1>${component}</h1>
    </main>
  );
}
`;
    }
    if (extension === "ts" || extension === "js") {
      return `export function ${component.toLowerCase()}() {
  return null;
}
`;
    }
    if (extension === "css") return `/* ${base} styles */
`;
    if (extension === "json") return "{}\n";
    if (extension === "md") return `# ${base}
`;
    return "";
  }
