  function init() {
    if (document.getElementById("lasso-root")) {
      console.log("[lasso] already initialized");
      return;
    }
    const dom = getDOM();
    buildToolbar();
    buildPinCompose();
    buildPinThread();
    buildGitPanel();
    buildTodoPanel();
    buildNotepadPanel();
    buildClipboardPanel();
    buildTaskPanel();
    buildPagePanel();
    buildPrompt();
    buildDrag();
    buildCommandBar();
    initErrorListeners();
    connectBridge();
    initCollabPagehide();
    initCursorTracking();
    function updatePositions() {
      if (state.selectMode && state.hovered) {
        updateHoverVisual(state.hovered);
      }
      renderRemoteBoxes();
      if (state.commentThreads.size > 0) {
        renderCommentPins();
      }
      if (state.selected) {
        updateSelectedVisual();
        if (!state.promptDragged) {
          positionPrompt(state.selected);
        }
      }
    }
    window.addEventListener("scroll", updatePositions, true);
    window.addEventListener("resize", updatePositions);
    document.addEventListener(
      "mousemove",
      (event) => {
        if (!state.selectMode) return;
        const target = event.target;
        if (!(target instanceof Element)) return;
        if (dom.isLassoElement(target)) return;
        setHovered(target);
      },
      true
    );
    document.addEventListener(
      "click",
      (event) => {
        const target = event.target;
        if (state.commentMode) {
          if (target && dom.isLassoElement(target)) return;
          event.preventDefault();
          event.stopPropagation();
          event.stopImmediatePropagation();
          closePinThread();
          openPinCompose(event.clientX, event.clientY);
          return;
        }
        if (!state.selectMode) return;
        if (!target || dom.isLassoElement(target)) return;
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();
        state.selected = target;
        state.elementRegistry.set(elementKey(target), target);
        updateLockChip();
        sendPresenceUpdate({});
        state.promptDragged = false;
        dom.hoverBox.style.display = "none";
        updateSelectedVisual();
        openPromptForSelected(target);
      },
      true
    );
    document.addEventListener("keydown", (event) => {
      if ((event.metaKey || event.ctrlKey) && event.key === "k") {
        event.preventDefault();
        event.stopPropagation();
        if (isCommandBarOpen()) {
          closeCommandBar();
        } else {
          openCommandBar();
        }
        return;
      }
      if (event.key !== "Escape") return;
      if (isCommandBarOpen()) {
        closeCommandBar();
        return;
      }
      if (isPinComposeOpen()) {
        closePinCompose();
        setCommentMode(false);
        return;
      }
      if (isPinThreadOpen()) {
        closePinThread();
        return;
      }
      if (isPagePanelOpen()) {
        closePagePanel();
        return;
      }
      if (isPromptOpen()) {
        cancelPrompt(true);
        return;
      }
      if (state.dragMode) {
        resetDrag(true);
        setDragMode(false);
        return;
      }
      if (state.selectMode) {
        setSelectMode(false);
        return;
      }
      if (state.previewMode) {
        setPreviewMode2(false);
        return;
      }
      if (state.commentMode) {
        setCommentMode(false);
        return;
      }
    });
    setSelectMode(false);
    console.log("[lasso] overlay ready");
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
